class UnionFind {
    constructor(size) {
        this.parent = Array(size).fill(0).map((_, i) => i);
    }

    find(x) {
        // path compression: find the actual root of the tree, and set all nodes on the path to point to it directly
        while (this.parent[x]!== x) {
            // recursively replace this node's parent with its true root, until we find the one at the end
            let root = this.parent[x];
            this.parent[x] = root; // note this isn't necessary, but is a tiny optimization
            x = this.parent[x];
        }
        return x;
    }

    union(x, y) {
        // find the root of each tree with find, then merge the two trees together
        let rootX = this.find(x);
        let rootY = this.find(y);
        // if we didn't union before, parent[rootY] has never been set, so it's -1
        if (rootX!== rootY) this.parent[rootY] = rootX; // attach the secondary tree to the first one
    }
}
